namespace sv_d33d45e8adb94d1ab1d9e9c9d12896b8.Components.Pages.Apply;

// Mutable view models used during form editing
public record WorkEntryModel
{
    public string Company { get; init; } = string.Empty;
    public string Title { get; init; } = string.Empty;
    public DateTime StartDate { get; init; } = DateTime.Today;
    public DateTime? EndDate { get; init; }
    public bool IsCurrent { get; init; }
    public string Description { get; init; } = string.Empty;
}

public record ReferenceModel
{
    public string Name { get; init; } = string.Empty;
    public string Relationship { get; init; } = string.Empty;
    public string Email { get; init; } = string.Empty;
    public string Phone { get; init; } = string.Empty;
}

@namespace sv_d33d45e8adb94d1ab1d9e9c9d12896b8.Components.Pages.Apply

<div class="step-content-panel">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullName = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = (string?)e.Value ?? string.Empty" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => Address = (string?)e.Value ?? string.Empty"></textarea>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ValidateEmail(Email);
            if (!emailValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}

@namespace sv_d33d45e8adb94d1ab1d9e9c9d12896b8.Components.Pages.Apply

<div class="step-content-panel">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       CanRemove="Entries.Count > 1"
                       OnChanged="entry => UpdateEntry(index, entry)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync(Entries)">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new() { new() };
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateEntry(int index, WorkEntryModel updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Company name and job title are required for all entries.";
                return;
            }
        }

        OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_d33d45e8adb94d1ab1d9e9c9d12896b8.Components.Pages.Apply

<div class="step-content-panel">
    <h3>References</h3>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="References[index]"
                       Index="index"
                       CanRemove="References.Count > 2"
                       OnChanged="entry => UpdateReference(index, entry)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync(References)">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new() { new(), new() };
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateReference(int index, ReferenceModel updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Name, relationship, and email are required for all references.";
                return;
            }
        }

        OnNext.InvokeAsync(References);
    }
}

@namespace sv_d33d45e8adb94d1ab1d9e9c9d12896b8.Components.Pages.Apply

<div class="step-content-panel">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <textarea rows="12" class="cover-letter-textarea"
                  value="@CoverLetter"
                  @oninput="e => CoverLetter = (string?)e.Value ?? string.Empty"
                  maxlength="@MaxCharacters"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="char-count @(CoverLetter.Length > MaxCharacters ? "over-limit" : "")">
            @CoverLetter.Length / @MaxCharacters characters
        </div>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync(CoverLetter)">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnBack { get; set; }

    private const int MaxCharacters = 2000;

    private void HandleNext()
    {
        OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_d33d45e8adb94d1ab1d9e9c9d12896b8.Components.Pages.Apply

<div class="step-content-panel">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h4>✓ Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
