    private void GoToStep(int step)
    {
        if (step <= currentStep || completedSteps.Contains(step))
            currentStep = step;
    }

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleWorkHistoryBack(List<WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 0;
    }

    private void HandleReferencesNext(List<ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleReferencesBack(List<ReferenceModel> refs)
    {
        references = refs;
        currentStep = 1;
