    private bool IsCurrent => Entry.IsCurrent;
    private string StartDateString => Entry.StartDate.ToString("yyyy-MM-dd");
    private string? EndDateString => Entry.EndDate?.ToString("yyyy-MM-dd");

    private void Update(WorkEntryModel updated) => OnChanged.InvokeAsync(updated);

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var date = string.IsNullOrEmpty(val) ? DateTime.Today : DateTime.Parse(val);
        Update(Entry with { StartDate = date });
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var date = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        Update(Entry with { EndDate = date });
    }

    private void OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        Update(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }
}

